package org.eclipse.rdf4j.http.server.repository.transaction;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;

import org.eclipse.rdf4j.http.protocol.Protocol;
import org.eclipse.rdf4j.query.BooleanQuery;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.repository.Repository;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.rio.ParserConfig;
import org.junit.jupiter.api.Test;
import org.slf4j.MDC;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;
import org.springframework.web.servlet.ModelAndView;

class TransactionControllerQueryLoggingContextTest {

	@Test
	void transactionQueryCapturesItsHttpRequestOptionsOnTheOwnerThread() throws Exception {
		String queryText = "ASK {}";
		Repository repository = mock(Repository.class);
		RepositoryConnection connection = mock(RepositoryConnection.class);
		BooleanQuery query = mock(BooleanQuery.class);
		when(repository.getConnection()).thenReturn(connection);
		when(connection.getParserConfig()).thenReturn(new ParserConfig());
		when(connection.prepareQuery(QueryLanguage.SPARQL, queryText, null)).thenReturn(query);
		AtomicReference<Map<String, String>> observed = new AtomicReference<>();
		when(query.evaluate()).thenAnswer(invocation -> {
			Map<String, String> context = new HashMap<>();
			for (String key : List.of("httpMethod", "httpRequestPath", "httpAccept", "httpTimeoutSeconds")) {
				context.put(key, MDC.get("org.eclipse.rdf4j." + key));
			}
			observed.set(context);
			return true;
		});
		try (Transaction transaction = new Transaction(repository)) {
			ActiveTransactionRegistry.INSTANCE.register(transaction);
			try {
				MockHttpServletRequest request = new MockHttpServletRequest();
				String path = "/repositories/test-repo/transactions/" + transaction.getID();
				request.setRequestURI(path);
				request.setPathInfo("test-repo/transactions/" + transaction.getID());
				request.setAttribute("repositoryID", "test-repo");
				request.setMethod("PUT");
				request.setContentType(Protocol.FORM_MIME_TYPE);
				request.setParameter(Protocol.ACTION_PARAM_NAME, Protocol.Action.QUERY.name());
				request.setParameter(Protocol.QUERY_PARAM_NAME, queryText);
				request.setParameter(Protocol.TIMEOUT_PARAM_NAME, "29");
				request.addHeader("Accept", "application/sparql-results+json");
				MockHttpServletResponse response = new MockHttpServletResponse();
				Map<String, String> before = MDC.getCopyOfContextMap();
				TransactionController controller = new TransactionController();
				ModelAndView modelAndView = controller.handleRequestInternal(request, response);
				modelAndView.getView().render(modelAndView.getModel(), request, response);

				assertThat(observed.get()).containsEntry("httpMethod", "PUT")
						.containsEntry("httpRequestPath", path)
						.containsEntry("httpAccept", "application/sparql-results+json")
						.containsEntry("httpTimeoutSeconds", "29");
				if (before == null) {
					assertThat(MDC.getCopyOfContextMap()).isNullOrEmpty();
				} else {
					assertThat(MDC.getCopyOfContextMap()).isEqualTo(before);
				}
			} finally {
				ActiveTransactionRegistry.INSTANCE.deregister(transaction);
			}
		}
	}
}
